var e=[`situation`,`thoughts`,`feelings`,`bodyFeelings`,`actions`,`actualNeed`,`childhoodMemories`],t=e=>[{key:`situation`,title:`Что произошло?`,hint:e(`Пары фраз достаточно — где ты, с кем, в какой момент.`,`Пары фраз достаточно — где вы, с кем, в какой момент.`),example:`Например: позвонил папа, начал расспрашивать про работу — и я чувствую, что «выключаюсь».`,required:!0,rows:3},{key:`thoughts`,title:`Что говорит этот режим?`,hint:e(`Его голос внутри — что он тебе твердит, во что верит.`,`Его голос внутри — что он вам твердит, во что верит.`),example:`Например: «не лезь, не показывай, никому по-настоящему не интересно».`,rows:2},{key:`feelings`,title:e(`Что ты чувствуешь?`,`Что вы чувствуете?`),hint:`Эмоции — и как это отзывается в теле.`,example:`Например: пустота и отрешённость, а под ними — обида; в груди тяжесть.`,rows:2},{key:`bodyFeelings`,title:`Что с телом?`,hint:`Где это отзывается и как.`,example:`Например: тяжесть в груди, плечи сводит, голос становится плоским.`,rows:2},{key:`actions`,title:e(`Что тянет сделать?`,`Что тянет сделать?`),hint:e(`Как режим тянет тебя поступить прямо сейчас.`,`Как режим тянет вас поступить прямо сейчас.`),example:`Например: свернуть разговор побыстрее, лечь и листать ленту.`,rows:2},{key:`actualNeed`,title:e(`Что тебе было нужно?`,`Что вам было нужно?`),hint:e(`Не режиму — тебе. Чего не хватило в тот момент.`,`Не режиму — вам. Чего не хватило в тот момент.`),example:e(`Например: чтобы спросили, как я, а не как работа.`,`Например: чтобы спросили, как я, а не как работа.`),rows:2},{key:`childhoodMemories`,title:`Откуда это знакомо?`,hint:`Может, из детства? Похожее чувство, похожая ситуация.`,example:`Например: когда мама приходила уставшая — было ясно: лучше не подходить.`,rows:3}];export{t as n,e as t};